<div className="grid grid-cols-1 md:grid-cols-3 gap-3">
  <div className="space-y-1">
    <label className="text-xs font-medium text-muted-foreground ml-1">
      Quantidade Atual
    </label>
    <Input
      data-mia-field="quantidade_atual"
      type="number"
      min="0"
      step="0.001"
      value={produto.quantidade_atual || 0}
      onChange={(e) => {
        const updatedProdutos = produtos.map(
          (p) =>
            p.id === produto.id
              ? {
                  ...p,
                  quantidade_atual:
                    parseFloat(
                      e.target.value,
                    ) || 0,
                }
              : p,
        );
        setProdutos(updatedProdutos);
      }}
      className="bg-white dark:bg-black/40 border-[#57715B]/10 dark:border-white/5 rounded-xl h-10"
    />
  </div>
  <div className="space-y-1">
    <label className="text-xs font-medium text-muted-foreground ml-1">
      Quantidade Máxima
    </label>
    <Input
      type="number"
      min="0"
      step="0.001"
      value={produto.quantidade_maxima || 100}
      onChange={(e) => {
        const updatedProdutos = produtos.map(
          (p) =>
            p.id === produto.id
              ? {
                  ...p,
                  quantidade_maxima:
                    parseFloat(
                      e.target.value,
                    ) || 100,
                }
              : p,
        );
        setProdutos(updatedProdutos);
      }}
      className="bg-white dark:bg-black/40 border-[#57715B]/10 dark:border-white/5 rounded-xl h-10"
    />
  </div>
</div>

<Textarea
  placeholder="Descrição"
  value={produto.descricao || ''}
