    const updatedProdutos = produtos.map((p) =>
      p.id === produto.id
        ? { ...p, descricao: e.target.value }
        : p,
    );
    setProdutos(updatedProdutos);
  }}
  className="bg-white dark:bg-black/40 border-[#57715B]/10 dark:border-white/5 rounded-xl min-h-[80px]"
/>

