import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'
import { getDegustToken } from '../_shared/degust-token.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-application',
}

const DEGUST_API_BASE = 'https://lx-degust-api-integracao-prd.azurewebsites.net'
const DEGUST_FRANQUIA = 3489

interface DegustTransaction {
  codigoLoja: string
  nomeLoja: string
  dataCaixa: string
  hora: string
  codigoProduto: string
  nomeProduto: string
  quantidade: number
  valorUnitario: number
}

interface AggregatedSale {
  degust_codigo: number
  degust_nome: string
  quantidade: number
  valor_total: number
  num_transacoes: number
}

// Fetch sales for a single day from Degust API
async function fetchDayFromDegust(
  token: string,
  codigoLoja: number,
  date: string
): Promise<DegustTransaction[]> {
  const url = `${DEGUST_API_BASE}/api/financeiro/movimentacao-produtos?CodigoFranquia=${DEGUST_FRANQUIA}&CodigoLoja=${codigoLoja}&DataCaixa=${date}&api-version=1.0`

  const response = await fetch(url, {
    headers: { 'Authorization': `Bearer ${token}` },
  })

  if (!response.ok) {
    const text = await response.text()
    console.error(`[degust-sync] Error fetching ${date}: ${response.status} - ${text}`)
    if (response.status === 401) {
      throw new Error('TOKEN_EXPIRED')
    }
    return []
  }

  return await response.json()
}

// Aggregate transactions by product code for a single day
