  if (products) {
    for (const p of products) {
      productInfo[p.id] = { nome: p.nome, setor: p.setor }
    }
  }

  // WEEKDAY_MAP (JS getDay: 0=Sunday)
  const WEEKDAY_MAP: Record<number, string> = {
    0: 'domingo', 1: 'segunda-feira', 2: 'terça-feira', 3: 'quarta-feira',
    4: 'quinta-feira', 5: 'sexta-feira', 6: 'sábado'
  }

  // Build ProductHistory[] format grouped by produto_master_id
  const grouped: Record<number, any> = {}
  for (const sale of (salesData || [])) {
    const pmId = sale.produto_master_id
    if (!pmId) continue

    if (!grouped[pmId]) {
      const info = productInfo[pmId]
      grouped[pmId] = {
        productName: info?.nome || sale.degust_nome,
        productCode: pmId.toString(),
        category: info?.setor || 'DEGUST',
        storeName: storeName,
        salesHistory: [],
        isFromDb: true,
      }
    }

    const saleDate = new Date(sale.data + 'T12:00:00Z')
    const weekday = WEEKDAY_MAP[saleDate.getUTCDay()]

    // Check if this date already exists (multiple degust products mapping to same master)
    const existing = grouped[pmId].salesHistory.find((s: any) => s.date === sale.data)
    if (existing) {
      existing.quantity += Number(sale.quantidade)
      existing.total = (existing.total || 0) + Number(sale.valor_total)
    } else {
      grouped[pmId].salesHistory.push({
        date: sale.data,
        quantity: Number(sale.quantidade),
        weekday,
        total: Number(sale.valor_total),
        avgPrice: Number(sale.quantidade) > 0 ? Number(sale.valor_total) / Number(sale.quantidade) : 0,
      })
    }
  }

  const productHistories = Object.values(grouped)

  return new Response(
    JSON.stringify({
