      meta: {
        startDate,
        endDate,
        totalDays: allDates.length,
        cachedDays: cachedSet.size,
        newlySynced: missingDates.length,
        syncedRows: syncedCount,
        errors: errorCount,
        productsFound: productHistories.length,
