  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-application',
}

const DEGUST_API_BASE = 'https://lx-degust-api-integracao-prd.azurewebsites.net'
const DEGUST_FRANQUIA = 3489

interface DegustTransaction {
  codigoLoja: string
  nomeLoja: string
  dataCaixa: string
  hora: string
  codigoProduto: string
  nomeProduto: string
  quantidade: number
  valorUnitario: number
}

interface AggregatedSale {
  degust_codigo: number
  degust_nome: string
  quantidade: number
  valor_total: number
  num_transacoes: number
}

async function fetchDayFromDegust(token: string, codigoLoja: number, date: string): Promise<DegustTransaction[]> {
  const url = `${DEGUST_API_BASE}/api/financeiro/movimentacao-produtos?CodigoFranquia=${DEGUST_FRANQUIA}&CodigoLoja=${codigoLoja}&DataCaixa=${date}&api-version=1.0`
  const response = await fetch(url, { headers: { 'Authorization': `Bearer ${token}` } })
  if (!response.ok) {
    const text = await response.text()
    console.error(`[degust-sync] Error fetching ${date}: ${response.status} - ${text}`)
    if (response.status === 401) throw new Error('TOKEN_EXPIRED')
    return []
  }
  return await response.json()
}

function aggregateTransactions(transactions: DegustTransaction[]): AggregatedSale[] {
  const byProduct: Record<string, AggregatedSale> = {}
  for (const tx of transactions) {
    const code = tx.codigoProduto
    if (!byProduct[code]) {
      byProduct[code] = { degust_codigo: parseInt(code), degust_nome: tx.nomeProduto, quantidade: 0, valor_total: 0, num_transacoes: 0 }
    }
    byProduct[code].quantidade += tx.quantidade
    byProduct[code].valor_total += tx.quantidade * tx.valorUnitario
    byProduct[code].num_transacoes += 1
  }
  return Object.values(byProduct)
}

function getDateRange(start: string, end: string): string[] {
  const dates: string[] = []
  const current = new Date(start + 'T12:00:00Z')
  const endDate = new Date(end + 'T12:00:00Z')
  while (current <= endDate) {
    dates.push(current.toISOString().split('T')[0])
    current.setUTCDate(current.getUTCDate() + 1)
  }
  return dates
}

async function fetchInBatches<T>(items: string[], batchSize: number, fn: (item: string) => Promise<T>): Promise<{ date: string; result: T }[]> {
  const results: { date: string; result: T }[] = []
  for (let i = 0; i < items.length; i += batchSize) {
    const batch = items.slice(i, i + batchSize)
    const batchResults = await Promise.all(batch.map(async (date) => ({ date, result: await fn(date) })))
    results.push(...batchResults)
  }
  return results
}

