    const SUPABASE_SERVICE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!

    let DEGUST_TOKEN: string
    try {
      DEGUST_TOKEN = await getDegustToken()
    } catch (err) {
      return new Response(JSON.stringify({ error: `Failed to get Degust token: ${(err as Error).message}` }), { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
    }

    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY)
    const { startDate, endDate, lojaId = 4 } = await req.json()

    if (!startDate || !endDate) {
      return new Response(JSON.stringify({ error: 'startDate and endDate are required (YYYY-MM-DD)' }), { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
    }

    const { data: storeMapping } = await supabase.from('degust_stores').select('degust_loja_codigo').eq('loja_id', lojaId).single()
    if (!storeMapping) {
      return new Response(JSON.stringify({ error: `No Degust store mapping for loja_id=${lojaId}` }), { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
    }
    const degustLojaCode = storeMapping.degust_loja_codigo
    const STORE_NAMES: Record<number, string> = {
      2: 'MOMMA DOCES SAUDAVEIS (ASA SUL)',
      3: 'MOMMA DOCES SAUDAVEIS (ASA NORTE)',
      4: 'MOMMA DOCES SAUDAVEIS (LAGO SUL)',
      5: 'MOMMA DOCES SAUDAVEIS (AGUAS CLARAS)',
      6: 'MOMMA DOCES SAUDAVEIS (BRASILIA SHOPPING)',
    }
    const storeName = STORE_NAMES[lojaId] || `LOJA ${lojaId}`

    const { data: productMappings } = await supabase.from('degust_product_mapping').select('degust_codigo, produto_master_id')
    const productMap: Record<number, number> = {}
    if (productMappings) for (const m of productMappings) productMap[m.degust_codigo] = m.produto_master_id

    const allDates = getDateRange(startDate, endDate)
    const { data: cachedDates } = await supabase.from('degust_vendas_diarias').select('data').eq('loja_id', lojaId).gte('data', startDate).lte('data', endDate)
    const cachedSet = new Set((cachedDates || []).map((d: any) => d.data))
    const missingDates = allDates.filter(d => !cachedSet.has(d))

    console.log(`[degust-sync] Range: ${startDate} to ${endDate} | Total: ${allDates.length} | Cached: ${cachedSet.size} | Missing: ${missingDates.length}`)

    let syncedCount = 0
    let errorCount = 0

    if (missingDates.length > 0) {
      let currentToken = DEGUST_TOKEN
      const results = await fetchInBatches(missingDates, 5, async (date) => {
        try {
          return await fetchDayFromDegust(currentToken, degustLojaCode, date)
