        const aggregated = aggregateTransactions(transactions)
        if (aggregated.length === 0) { cachedSet.add(date); continue }
        const rows = aggregated.filter(sale => productMap[sale.degust_codigo]).map(sale => ({
          loja_id: lojaId,
          data: date,
          degust_codigo: sale.degust_codigo,
          degust_nome: sale.degust_nome,
          produto_master_id: productMap[sale.degust_codigo] || null,
          quantidade: sale.quantidade,
          valor_total: Math.round(sale.valor_total * 100) / 100,
          num_transacoes: sale.num_transacoes,
          synced_at: new Date().toISOString(),
