    if (readError) {
      return new Response(JSON.stringify({ error: 'Failed to read cached data', details: readError }), { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
    }

    const masterIds = [...new Set((salesData || []).map((s: any) => s.produto_master_id))]
    const { data: products } = await supabase.from('produtos_master').select('id, nome, setor').in('id', masterIds)
    const productInfo: Record<number, { nome: string; setor: string }> = {}
    if (products) for (const p of products) productInfo[p.id] = { nome: p.nome, setor: p.setor }

    const WEEKDAY_MAP: Record<number, string> = { 0: 'domingo', 1: 'segunda-feira', 2: 'terça-feira', 3: 'quarta-feira', 4: 'quinta-feira', 5: 'sexta-feira', 6: 'sábado' }
    const grouped: Record<number, any> = {}
    for (const sale of (salesData || [])) {
      const pmId = sale.produto_master_id
      if (!pmId) continue
      if (!grouped[pmId]) {
        const info = productInfo[pmId]
        grouped[pmId] = { productName: info?.nome || sale.degust_nome, productCode: pmId.toString(), category: info?.setor || 'DEGUST', storeName, salesHistory: [], isFromDb: true }
      }
      const saleDate = new Date(sale.data + 'T12:00:00Z')
      const weekday = WEEKDAY_MAP[saleDate.getUTCDay()]
      const existing = grouped[pmId].salesHistory.find((s: any) => s.date === sale.data)
      if (existing) {
        existing.quantity += Number(sale.quantidade)
        existing.total = (existing.total || 0) + Number(sale.valor_total)
      } else {
        grouped[pmId].salesHistory.push({ date: sale.data, quantity: Number(sale.quantidade), weekday, total: Number(sale.valor_total), avgPrice: Number(sale.quantidade) > 0 ? Number(sale.valor_total) / Number(sale.quantidade) : 0 })
      }
    }
    const productHistories = Object.values(grouped)

    return new Response(JSON.stringify({
      data: productHistories,
      meta: { startDate, endDate, totalDays: allDates.length, cachedDays: cachedSet.size, newlySynced: missingDates.length, syncedRows: syncedCount, errors: errorCount, productsFound: productHistories.length },
    }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
  } catch (err) {
    const message = (err as Error).message
    return new Response(JSON.stringify({ error: `Internal error: ${message}` }), { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
  }
})
