    // sobrescreve com o dia completo quando re-buscado).
    const missingDates = forceRefresh ? allDates : allDates.filter(d => !cachedSet.has(d))

    console.log(`[degust-sync] Range: ${startDate} to ${endDate} | Total: ${allDates.length} | Cached: ${cachedSet.size} | Missing: ${missingDates.length} | Force: ${forceRefresh}`)

    let syncedCount = 0
    let errorCount = 0

    if (missingDates.length > 0) {
      let currentToken = DEGUST_TOKEN
      const results = await fetchInBatches(missingDates, 5, async (date) => {
        try {
          return await fetchDayFromDegust(currentToken, degustLojaCode, date)
        } catch (err) {
          if ((err as Error).message === 'TOKEN_EXPIRED') {
            console.log(`[degust-sync] Token expired mid-sync, refreshing...`)
            currentToken = await getDegustToken(true)
            return await fetchDayFromDegust(currentToken, degustLojaCode, date)
          }
          console.error(`[degust-sync] Failed to fetch ${date}:`, err)
          return []
        }
      })

      for (const { date, result: transactions } of results) {
        const aggregated = aggregateTransactions(transactions)
        if (aggregated.length === 0) { cachedSet.add(date); continue }
        // Mantém produto NÃO mapeado (produto_master_id null) — descartar fazia a
        // venda de produto novo sumir do histórico até alguém mapear, sem recuperação
        const rows = aggregated.map(sale => ({
          loja_id: lojaId,
          data: date,
          degust_codigo: sale.degust_codigo,
          degust_nome: sale.degust_nome,
          produto_master_id: productMap[sale.degust_codigo] || null,
          quantidade: sale.quantidade,
          valor_total: Math.round(sale.valor_total * 100) / 100,
          num_transacoes: sale.num_transacoes,
          synced_at: new Date().toISOString(),
        }))
        if (rows.length > 0) {
          const { error } = await supabase.from('degust_vendas_diarias').upsert(rows, { onConflict: 'loja_id,data,degust_codigo' })
          if (error) { console.error(`[degust-sync] Insert error for ${date}:`, error); errorCount++ }
          else { syncedCount += rows.length }
        }
      }
    }

    const { data: salesData, error: readError } = await supabase.from('degust_vendas_diarias').select('data, quantidade, valor_total, produto_master_id, degust_nome, degust_codigo').eq('loja_id', lojaId).gte('data', startDate).lte('data', endDate).not('produto_master_id', 'is', null)
    if (readError) {
      return new Response(JSON.stringify({ error: 'Failed to read cached data', details: readError }), { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
    }

    const masterIds = [...new Set((salesData || []).map((s: any) => s.produto_master_id))]
    const { data: products } = await supabase.from('produtos_master').select('id, nome, setor').in('id', masterIds)
    const productInfo: Record<number, { nome: string; setor: string }> = {}
    if (products) for (const p of products) productInfo[p.id] = { nome: p.nome, setor: p.setor }

    const WEEKDAY_MAP: Record<number, string> = { 0: 'domingo', 1: 'segunda-feira', 2: 'terça-feira', 3: 'quarta-feira', 4: 'quinta-feira', 5: 'sexta-feira', 6: 'sábado' }
    const grouped: Record<number, any> = {}
    for (const sale of (salesData || [])) {
      const pmId = sale.produto_master_id
      if (!pmId) continue
      if (!grouped[pmId]) {
        const info = productInfo[pmId]
        grouped[pmId] = { productName: info?.nome || sale.degust_nome, productCode: pmId.toString(), category: info?.setor || 'DEGUST', storeName, salesHistory: [], isFromDb: true }
      }
      const saleDate = new Date(sale.data + 'T12:00:00Z')
      const weekday = WEEKDAY_MAP[saleDate.getUTCDay()]
      const existing = grouped[pmId].salesHistory.find((s: any) => s.date === sale.data)
      if (existing) {
        existing.quantity += Number(sale.quantidade)
        existing.total = (existing.total || 0) + Number(sale.valor_total)
      } else {
        grouped[pmId].salesHistory.push({ date: sale.data, quantity: Number(sale.quantidade), weekday, total: Number(sale.valor_total), avgPrice: Number(sale.quantidade) > 0 ? Number(sale.valor_total) / Number(sale.quantidade) : 0 })
      }
    }
    const productHistories = Object.values(grouped)

    return new Response(JSON.stringify({
      data: productHistories,
      meta: { startDate, endDate, totalDays: allDates.length, cachedDays: cachedSet.size, newlySynced: missingDates.length, syncedRows: syncedCount, errors: errorCount, productsFound: productHistories.length },
    }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
  } catch (err) {
    const message = (err as Error).message
    return new Response(JSON.stringify({ error: `Internal error: ${message}` }), { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } })
  }
})

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

export class DegustTokenError extends Error {
  constructor(msg: string) {
    super(msg)
    this.name = 'DegustTokenError'
  }
}

export async function getDegustToken(forceRefresh = false): Promise<string> {
  const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!
  const SUPABASE_SERVICE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY)

  if (!forceRefresh) {
    const { data, error } = await supabase.from('degust_auth').select('token, expires_at').eq('id', 1).maybeSingle()
    if (error) throw new DegustTokenError(`Failed to read degust_auth: ${error.message}`)
    if (data?.token && data.token !== 'ERROR') {
      const expiresMs = new Date(data.expires_at).getTime()
      const fiveMinFromNow = Date.now() + 5 * 60 * 1000
      if (expiresMs > fiveMinFromNow) return data.token
      console.log(`[degust-token] Token expires at ${data.expires_at}, refreshing...`)
    } else {
      console.log('[degust-token] No token in DB, refreshing...')
    }
  }

  const refreshUrl = `${SUPABASE_URL}/functions/v1/degust-auth-refresh`
  const refreshRes = await fetch(refreshUrl, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${SUPABASE_SERVICE_KEY}`, 'Content-Type': 'application/json' },
  })
  if (!refreshRes.ok) {
    const errText = await refreshRes.text()
    throw new DegustTokenError(`degust-auth-refresh failed: ${refreshRes.status} - ${errText}`)
  }
  const { data: fresh, error: freshErr } = await supabase.from('degust_auth').select('token').eq('id', 1).single()
  if (freshErr || !fresh?.token || fresh.token === 'ERROR') {
    throw new DegustTokenError(`Token still not available after refresh: ${freshErr?.message ?? 'unknown'}`)
  }
  return fresh.token
}

